/* ---------- Independence Special (2nd – 31st October 2026) ----------
   Special prices apply automatically from PROMO.start up to (not including) PROMO.end,
   then the site reverts to the regular prices below with no further edits needed.
   To change or remove the promo, edit the prices/dates here (or delete PROMO entirely). */
const IMG_INDEPENDENCE_SPECIAL = "data:image/jpeg;base64,";
const PROMO = {
  start: new Date(2026, 9, 2),  // 2 Oct 2026, 00:00
  end: new Date(2026, 10, 1),   // 1 Nov 2026, 00:00 (so the last day is 31 Oct)
  prices: { big: 8000, small: 5000 }, // 500ml and 330ml parfaits
};
// Resets to false on every page load/reload, so the pop-up returns each time the site is opened
let promoDismissedThisLoad = false;
const PROMO_ACTIVE = (() => {
  const now = new Date();
  return now >= PROMO.start && now < PROMO.end;
})();

const REGULAR_PRODUCTS = [
  { id: "big", name: "Big Parfait (500ml)", price: 12000, kind: "parfait", desc: "Greek yogurt layered with fresh fruit, in our full-size cup.", image: IMG_BIG },
  { id: "small", name: "Small Parfait (330ml)", price: 8500, kind: "parfait", desc: "The same layered parfait, in a smaller portion.", image: IMG_SMALL },
  { id: "yogurt35", name: "Plain Yoghurt (35cl)", price: 2000, kind: "yogurt", desc: "Yogurt on its own, unsweetened by fruit or toppings.", image: IMG_YOGURT_35 },
  { id: "yogurt50", name: "Plain Yoghurt (50cl)", price: 3000, kind: "yogurt", desc: "Yogurt on its own, unsweetened by fruit or toppings.", image: IMG_YOGURT_50 },
];

// Every price shown or charged on the site comes from PRODUCTS, so the special
// flows through the menu, cart, order total and saved orders automatically.
const PRODUCTS = REGULAR_PRODUCTS.map((p) =>
  PROMO_ACTIVE && PROMO.prices[p.id] != null
    ? { ...p, regularPrice: p.price, price: PROMO.prices[p.id] }
    : p
);

function naira(n) {
  return "₦" + n.toLocaleString("en-NG");
}

/* Shows the price, with the regular price struck through while a special is running */
function PriceLabel({ p }) {
  return (
    <>
      {p.regularPrice && (
        <span className="text-xs font-normal text-gray-400 line-through mr-1.5">{naira(p.regularPrice)}</span>
      )}
      {naira(p.price)}
    </>
  );
}

