function MenuPage({ setPage, cartState }) {
  const { cart, addToCart } = cartState;
  const [productId, setProductId] = useState("big");
  const [qty, setQty] = useState(1);
  const [fruits, setFruits] = useState([]);
  const [toppings, setToppings] = useState([]);
  const [justAdded, setJustAdded] = useState(false);

  const product = PRODUCTS.find((p) => p.id === productId);
  const isParfait = product.kind === "parfait";
  const lineTotal = product.price * qty;
  const cartTotal = cart.reduce((sum, i) => sum + PRODUCTS.find((p) => p.id === i.productId).price * i.qty, 0);
  const cartCount = cart.reduce((n, i) => n + i.qty, 0);

  function toggle(list, setList, item) {
    setList(list.includes(item) ? list.filter((x) => x !== item) : [...list, item]);
  }

  function handleAddToCart() {
    addToCart({ productId, qty, fruits, toppings });
    setQty(1);
    setFruits([]);
    setToppings([]);
    setJustAdded(true);
    setTimeout(() => setJustAdded(false), 2000);
  }

  return (
    <div className="max-w-5xl mx-auto px-5 py-14">
      <h1 className="serif text-4xl font-bold mb-3" style={{ color: NAVY }}>Menu</h1>
      <p className="sans text-gray-600 mb-10 max-w-xl">
        Parfait is available in two sizes, both prepared the same way: a base of Greek yogurt, layered with fresh
        fruit, with gummies, Maltesers, cashew nuts, and Skittles available as optional add-ins. Yoghurt is served plain.
      </p>

      <div className="mb-12">
        <h2 className="serif text-xl font-bold mb-4" style={{ color: GREEN_DARK }}>Parfait</h2>
        <div className="grid md:grid-cols-2 gap-6">
          {PRODUCTS.filter((p) => p.kind === "parfait").map((p) => (
            <div key={p.id} className="rounded-2xl border overflow-hidden" style={{ borderColor: "#E7E2D4" }}>
              <img src={p.image} alt={p.name} className="w-full object-cover" style={{ aspectRatio: "4 / 3" }} />
              <div className="p-6">
              <div className="flex items-baseline justify-between mb-3">
                <div className="serif font-bold text-xl" style={{ color: NAVY }}>{p.name}</div>
                <div className="sans font-bold" style={{ color: GREEN_DARK }}><PriceLabel p={p} /></div>
              </div>
              <div className="sans text-sm mb-4" style={{ color: "#4B4B4B" }}>Base: Greek yogurt</div>
              <div className="sans text-xs font-semibold tracking-wide text-gray-400 mb-2">FRUIT OPTIONS</div>
              <div className="flex flex-wrap gap-2 mb-4">
                {FRUITS.map((f) => (
                  <span key={f} className="sans text-xs px-2.5 py-1 rounded-full" style={{ backgroundColor: "#EAF5EC", color: GREEN_DARK }}>{f}</span>
                ))}
              </div>
              <div className="sans text-xs font-semibold tracking-wide text-gray-400 mb-2">TOPPING ADD-INS</div>
              <div className="flex flex-wrap gap-2">
                {TOPPINGS.map((t) => (
                  <span key={t} className="sans text-xs px-2.5 py-1 rounded-full" style={{ backgroundColor: "#FBF2DC", color: "#8A6A0E" }}>{t}</span>
                ))}
              </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div>
        <h2 className="serif text-xl font-bold mb-4" style={{ color: GREEN_DARK }}>Yoghurt</h2>
        <div className="grid sm:grid-cols-2 gap-6">
          {PRODUCTS.filter((p) => p.kind === "yogurt").map((p) => (
            <div key={p.id} className="rounded-2xl border overflow-hidden" style={{ borderColor: "#E7E2D4" }}>
              <img src={p.image} alt={p.name} className="w-full object-cover" style={{ aspectRatio: "4 / 3" }} />
              <div className="p-6">
                <div className="flex items-baseline justify-between mb-2">
                  <div className="serif font-bold text-xl" style={{ color: NAVY }}>{p.name}</div>
                  <div className="sans font-bold" style={{ color: GREEN_DARK }}><PriceLabel p={p} /></div>
                </div>
                <p className="sans text-sm text-gray-600">{p.desc}</p>
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="mt-14 rounded-2xl border p-6 sm:p-8" style={{ borderColor: "#E7E2D4", backgroundColor: "#FBF9F2" }}>
        <h2 className="serif text-xl font-bold mb-1" style={{ color: NAVY }}>Build your order</h2>
        <p className="sans text-sm text-gray-600 mb-6">
          Add as many items as you like — big parfait, small parfait, either yoghurt size — then review it all together.
        </p>

        <div className="sans text-sm font-semibold mb-3" style={{ color: NAVY }}>Item</div>
        <div className="grid sm:grid-cols-3 gap-3 mb-6">
          {PRODUCTS.map((p) => (
            <button
              key={p.id}
              onClick={() => setProductId(p.id)}
              className="text-left rounded-xl border px-4 py-3 sans press"
              style={{
                borderColor: productId === p.id ? GREEN : "#E7E2D4",
                backgroundColor: productId === p.id ? "#EAF5EC" : "white",
              }}
            >
              <div className="font-semibold text-sm mb-0.5" style={{ color: NAVY }}>{p.name}</div>
              <div className="text-sm font-bold" style={{ color: GREEN_DARK }}><PriceLabel p={p} /></div>
            </button>
          ))}
        </div>

        {isParfait && (
          <>
            <div className="sans text-sm font-semibold mb-3" style={{ color: NAVY }}>Fruit</div>
            <div className="flex flex-wrap gap-2 mb-6">
              {FRUITS.map((f) => (
                <button
                  key={f}
                  onClick={() => toggle(fruits, setFruits, f)}
                  className="sans text-sm px-3 py-1.5 rounded-full border press"
                  style={{
                    borderColor: fruits.includes(f) ? GREEN : "#E7E2D4",
                    backgroundColor: fruits.includes(f) ? GREEN : "white",
                    color: fruits.includes(f) ? "white" : "#333",
                  }}
                >
                  {f}
                </button>
              ))}
            </div>

            <div className="sans text-sm font-semibold mb-3" style={{ color: NAVY }}>Toppings</div>
            <div className="flex flex-wrap gap-2 mb-6">
              {TOPPINGS.map((t) => (
                <button
                  key={t}
                  onClick={() => toggle(toppings, setToppings, t)}
                  className="sans text-sm px-3 py-1.5 rounded-full border press"
                  style={{
                    borderColor: toppings.includes(t) ? GOLD : "#E7E2D4",
                    backgroundColor: toppings.includes(t) ? GOLD : "white",
                    color: toppings.includes(t) ? NAVY : "#333",
                  }}
                >
                  {t}
                </button>
              ))}
            </div>
          </>
        )}

        <div className="sans text-sm font-semibold mb-3" style={{ color: NAVY }}>Quantity</div>
        <div className="flex items-center gap-4 mb-7">
          <button onClick={() => setQty(Math.max(1, qty - 1))} className="w-9 h-9 rounded-full border flex items-center justify-center press bg-white" style={{ borderColor: "#E7E2D4" }}>
            <Minus size={15} />
          </button>
          <span className="sans font-semibold w-6 text-center">{qty}</span>
          <button onClick={() => setQty(qty + 1)} className="w-9 h-9 rounded-full border flex items-center justify-center press bg-white" style={{ borderColor: "#E7E2D4" }}>
            <Plus size={15} />
          </button>
        </div>

        <div className="flex items-center justify-between rounded-xl p-4 mb-6 bg-white">
          <span className="sans text-sm font-semibold" style={{ color: NAVY }}>This item's total</span>
          <span className="sans text-xl font-bold" style={{ color: GREEN_DARK }}>{naira(lineTotal)}</span>
        </div>

        <button
          onClick={handleAddToCart}
          className="px-6 py-3 rounded-full font-semibold text-white sans flex items-center gap-1.5 hover-lift press"
          style={{ backgroundColor: justAdded ? GREEN_DARK : GREEN }}
        >
          {justAdded ? <><Check size={17} /> Added to cart</> : <>Add to cart <Plus size={17} /></>}
        </button>

        {cartCount > 0 && (
          <div className="mt-6 pt-6 border-t flex items-center justify-between flex-wrap gap-3" style={{ borderColor: "#E7E2D4" }}>
            <span className="sans text-sm" style={{ color: NAVY }}>
              <span className="font-semibold">{cartCount}</span> item{cartCount !== 1 ? "s" : ""} in cart ·{" "}
              <span className="font-semibold" style={{ color: GREEN_DARK }}>{naira(cartTotal)}</span>
            </span>
            <button
              onClick={() => setPage("order")}
              className="px-5 py-2.5 rounded-full font-semibold text-white sans flex items-center gap-1.5 hover-lift press"
              style={{ backgroundColor: NAVY }}
            >
              Review order <ChevronRight size={16} />
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

