function FeedbackPage() {
  const CATEGORIES = ["Compliment", "Suggestion", "Issue", "Other"];
  const [rating, setRating] = useState(0);
  const [category, setCategory] = useState("Compliment");
  const [message, setMessage] = useState("");
  const [name, setName] = useState("");
  const [contact, setContact] = useState("");
  const [submitted, setSubmitted] = useState(false);

  const canSubmit = message.trim().length > 0;

  async function saveFeedbackToDatabase() {
    try {
      const { error } = await supabase.from("feedback").insert({
        name,
        contact,
        category,
        rating: rating || null,
        message: message.trim(),
      });
      if (error) throw error;
    } catch (err) {
      console.error("Could not save feedback to database:", err);
    }
  }

  function handleSubmit() {
    saveFeedbackToDatabase();
    setSubmitted(true);
  }

  function buildFeedbackMessage() {
    const lines = [
      `Feedback from Global Daddy's website`,
      ``,
      `Category: ${category}`,
      `Rating: ${rating ? `${rating}/5` : "not given"}`,
      ``,
      message.trim(),
      ``,
      `Name: ${name || "-"}`,
      `Contact: ${contact || "-"}`,
    ];
    return lines.join("\n");
  }

  const feedbackText = buildFeedbackMessage();
  const waLinks = PHONES.map((p) => ({
    phone: p,
    link: `https://wa.me/234${p.slice(1)}?text=${encodeURIComponent(feedbackText)}`,
  }));
  const mailtoLink = `mailto:${EMAIL}?subject=${encodeURIComponent("Feedback from website — " + category)}&body=${encodeURIComponent(feedbackText)}`;

  if (submitted) {
    return (
      <div className="max-w-lg mx-auto px-5 py-20 text-center">
        <div className="w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-6" style={{ backgroundColor: "#EAF5EC" }}>
          <Check size={28} style={{ color: GREEN_DARK }} />
        </div>
        <h1 className="serif text-3xl font-bold mb-3" style={{ color: NAVY }}>Ready to send</h1>
        <p className="sans text-gray-600 mb-8">
          Thank you for taking the time to share this. Choose how you'd like to send it through.
        </p>

        <div className="sans text-xs font-semibold tracking-wide text-gray-400 mb-3">SEND VIA WHATSAPP</div>
        <div className="flex flex-col gap-2.5 mb-7">
          {waLinks.map(({ phone, link }) => (
            <a
              key={phone}
              href={link}
              target="_blank"
              rel="noreferrer"
              className="flex items-center justify-center gap-2 px-6 py-3 rounded-full font-semibold text-white sans hover-lift press"
              style={{ backgroundColor: "#25D366" }}
            >
              <MessageCircle size={17} /> {phone}
            </a>
          ))}
        </div>

        <div className="sans text-xs font-semibold tracking-wide text-gray-400 mb-3">OR SEND VIA EMAIL</div>
        <a
          href={mailtoLink}
          className="inline-flex items-center justify-center gap-2 px-6 py-3 rounded-full font-semibold sans hover-lift press border"
          style={{ borderColor: NAVY, color: NAVY }}
        >
          <Mail size={17} /> {EMAIL}
        </a>

        <div className="mt-8">
          <button
            onClick={() => {
              setSubmitted(false);
              setRating(0);
              setCategory("Compliment");
              setMessage("");
              setName("");
              setContact("");
            }}
            className="sans text-sm"
            style={{ color: GREEN_DARK }}
          >
            ← Share more feedback
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto px-5 py-14">
      <h1 className="serif text-4xl font-bold mb-2" style={{ color: NAVY }}>Feedback &amp; suggestions</h1>
      <p className="sans text-gray-600 mb-8">
        We're a small family business, and every message helps us get better. Tell us what you think —
        good, bad, or somewhere in between.
      </p>

      <div className="mb-7">
        <div className="sans text-sm font-semibold mb-3" style={{ color: NAVY }}>How would you rate your experience?</div>
        <div className="flex gap-1.5">
          {[1, 2, 3, 4, 5].map((n) => (
            <button
              key={n}
              onClick={() => setRating(n)}
              aria-label={`Rate ${n} out of 5`}
              className="press"
            >
              <Star size={30} fill={n <= rating ? GOLD : "none"} style={{ color: GOLD }} />
            </button>
          ))}
        </div>
      </div>

      <div className="mb-7">
        <div className="sans text-sm font-semibold mb-3" style={{ color: NAVY }}>What's this about?</div>
        <div className="flex flex-wrap gap-2">
          {CATEGORIES.map((c) => (
            <button
              key={c}
              onClick={() => setCategory(c)}
              className="sans text-sm px-3.5 py-1.5 rounded-full border press"
              style={{
                borderColor: category === c ? GREEN : "#E7E2D4",
                backgroundColor: category === c ? GREEN : "white",
                color: category === c ? "white" : "#333",
              }}
            >
              {c}
            </button>
          ))}
        </div>
      </div>

      <div className="mb-7">
        <label className="sans text-sm font-semibold block mb-1.5" style={{ color: NAVY }}>Your message</label>
        <textarea
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          rows={5}
          className="w-full border rounded-lg px-3 py-2.5 sans text-sm"
          style={{ borderColor: "#E7E2D4" }}
          placeholder="What worked well, what didn't, or an idea for something new..."
        />
      </div>

      <div className="grid sm:grid-cols-2 gap-4 mb-8">
        <div>
          <label className="sans text-sm font-semibold block mb-1.5" style={{ color: NAVY }}>Your name (optional)</label>
          <input value={name} onChange={(e) => setName(e.target.value)} className="w-full border rounded-lg px-3 py-2.5 sans text-sm" style={{ borderColor: "#E7E2D4" }} placeholder="e.g. Amaka Obi" />
        </div>
        <div>
          <label className="sans text-sm font-semibold block mb-1.5" style={{ color: NAVY }}>Phone or email (optional)</label>
          <input value={contact} onChange={(e) => setContact(e.target.value)} className="w-full border rounded-lg px-3 py-2.5 sans text-sm" style={{ borderColor: "#E7E2D4" }} placeholder="If you'd like a reply" />
        </div>
      </div>

      <button
        disabled={!canSubmit}
        onClick={handleSubmit}
        className="w-full py-3.5 rounded-full font-semibold text-white sans disabled:opacity-40 press"
        style={{ backgroundColor: GREEN }}
      >
        Continue &amp; choose how to send
      </button>
      {!canSubmit && <p className="sans text-xs text-gray-400 mt-2 text-center">Add a message to continue.</p>}
    </div>
  );
}

function OrderPage({ cartState, setPage }) {
  const { cart, removeFromCart, updateCartQty, clearCart } = cartState;
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [address, setAddress] = useState("");
  const [notes, setNotes] = useState("");
  const [submitted, setSubmitted] = useState(false);
  const [copied, setCopied] = useState(false);
  const [paymentStatus, setPaymentStatus] = useState(null); // null | 'paid' | 'pending'
  const [paying, setPaying] = useState(false);
  const [verifying, setVerifying] = useState(false);
  const [verifyError, setVerifyError] = useState(null);
  const [saveError, setSaveError] = useState(false);
  const [showNotice, setShowNotice] = useState(() => {
    try {
      return sessionStorage.getItem("gd_lead_time_notice_seen") !== "true";
    } catch {
      return true;
    }
  });

  function dismissNotice() {
    setShowNotice(false);
    try {
      sessionStorage.setItem("gd_lead_time_notice_seen", "true");
    } catch {}
  }

  const lines = cart.map((item) => {
    const product = PRODUCTS.find((p) => p.id === item.productId);
    return { ...item, product, subtotal: product.price * item.qty };
  });
  const total = lines.reduce((sum, l) => sum + l.subtotal, 0);

  async function saveOrderToDatabase(status, reference) {
    try {
      const { error } = await supabase.from("orders").insert({
        customer_name: name,
        phone,
        address,
        notes,
        items: lines.map((l) => ({
          name: l.product.name,
          qty: l.qty,
          price: l.product.price,
          subtotal: l.subtotal,
          fruits: l.fruits,
          toppings: l.toppings,
        })),
        total,
        payment_method: status === "paid" ? "paystack" : "transfer",
        payment_status: status,
        payment_reference: reference || null,
      });
      if (error) throw error;
      setSaveError(false);
    } catch (err) {
      console.error("Could not save order to database:", err);
      setSaveError(true);
    }
  }

  async function verifyAndCompletePayment(reference) {
    setVerifying(true);
    setVerifyError(null);
    try {
      const res = await fetch("/api/verify-payment", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ reference }),
      });
      const data = await res.json();

      if (data.verified && Math.abs(data.amount - total) < 1) {
        setPaymentStatus("paid");
        await saveOrderToDatabase("paid", reference);
        setSubmitted(true);
      } else if (data.verified) {
        // Paystack confirms payment, but the amount doesn't match this cart —
        // treat cautiously rather than silently trusting it.
        setVerifyError(
          `We received a payment but the amount didn't match your order. Please contact us with this reference: ${reference}`
        );
      } else {
        setVerifyError(
          `We couldn't verify this payment. If money left your account, please contact us with this reference: ${reference}`
        );
      }
    } catch (err) {
      console.error("Verification request failed:", err);
      setVerifyError(
        `We couldn't confirm your payment right now. If money left your account, please contact us with this reference: ${reference}`
      );
    } finally {
      setVerifying(false);
    }
  }

  function payWithPaystack() {
    if (!window.PaystackPop) {
      alert("Payment is still loading — please try again in a moment.");
      return;
    }
    setPaying(true);
    setVerifyError(null);
    const handler = window.PaystackPop.setup({
      key: PAYSTACK_PUBLIC_KEY,
      email: email.trim() || "customer@globaldaddyparfait.com",
      amount: total * 100, // Paystack expects kobo
      currency: "NGN",
      ref: `GD-${Date.now()}`,
      metadata: {
        custom_fields: [
          { display_name: "Customer Name", variable_name: "customer_name", value: name },
          { display_name: "Phone", variable_name: "phone", value: phone },
        ],
      },
      callback: function (response) {
        setPaying(false);
        verifyAndCompletePayment(response.reference);
      },
      onClose: function () {
        setPaying(false);
      },
    });
    handler.openIframe();
  }

  function payByTransfer() {
    setPaymentStatus("pending");
    saveOrderToDatabase("pending", null);
    setSubmitted(true);
  }

  function buildMessage() {
    const out = [`New order from Global Daddy's website`, ``];
    lines.forEach((l) => {
      out.push(`Item: ${l.product.name} x${l.qty} — ${naira(l.subtotal)}`);
      if (l.product.kind === "parfait") {
        out.push(`  Fruit: ${l.fruits.length ? l.fruits.join(", ") : "no preference"}`);
        out.push(`  Toppings: ${l.toppings.length ? l.toppings.join(", ") : "none"}`);
      }
    });
    out.push(``, `Order total: ${naira(total)}`);
    out.push(``, `Name: ${name || "-"}`, `Phone: ${phone || "-"}`, `Delivery/pickup address: ${address || "-"}`);
    if (notes) out.push(`Notes: ${notes}`);
    return out.join("\n");
  }

  const canSubmit = name.trim() && phone.trim() && cart.length > 0;
  const message = buildMessage();
  const waLinks = PHONES.map((p) => ({
    phone: p,
    link: `https://wa.me/234${p.slice(1)}?text=${encodeURIComponent(message)}`,
  }));
  const mailtoLink = `mailto:${EMAIL}?subject=${encodeURIComponent("New order from website")}&body=${encodeURIComponent(message)}`;

  if (submitted) {
    return (
      <div className="max-w-lg mx-auto px-5 py-20 text-center">
        <div className="w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-6" style={{ backgroundColor: "#EAF5EC" }}>
          <Check size={28} style={{ color: GREEN_DARK }} />
        </div>
        {paymentStatus === "paid" ? (
          <>
            <h1 className="serif text-3xl font-bold mb-3" style={{ color: NAVY }}>Payment received!</h1>
            <p className="sans text-gray-600 mb-8">
              Your order is confirmed and paid. Let us know it's on the way in — send us the details below so
              we can start preparing it.
            </p>
          </>
        ) : (
          <>
            <h1 className="serif text-3xl font-bold mb-3" style={{ color: NAVY }}>Order saved</h1>
            <p className="sans text-gray-600 mb-8">
              Now send it to us — WhatsApp to any of our numbers, or straight to our email — then complete
              payment using the bank details below.
            </p>
          </>
        )}
        {saveError && (
          <p className="sans text-xs mb-6" style={{ color: "#B23A48" }}>
            (Your order didn't save to our system, but sending it below still reaches us directly.)
          </p>
        )}

        <div className="sans text-xs font-semibold tracking-wide text-gray-400 mb-3">SEND VIA WHATSAPP</div>
        <div className="flex flex-col gap-2.5 mb-7">
          {waLinks.map(({ phone, link }) => (
            <a
              key={phone}
              href={link}
              target="_blank"
              rel="noreferrer"
              className="flex items-center justify-center gap-2 px-6 py-3 rounded-full font-semibold text-white sans hover-lift press"
              style={{ backgroundColor: "#25D366" }}
            >
              <MessageCircle size={17} /> {phone}
            </a>
          ))}
        </div>

        <div className="sans text-xs font-semibold tracking-wide text-gray-400 mb-3">OR SEND VIA EMAIL</div>
        <a
          href={mailtoLink}
          className="inline-flex items-center justify-center gap-2 px-6 py-3 rounded-full font-semibold sans hover-lift press border"
          style={{ borderColor: NAVY, color: NAVY }}
        >
          <Mail size={17} /> {EMAIL}
        </a>

        {paymentStatus !== "paid" && (
        <div className="mt-10 rounded-2xl border p-6 text-left" style={{ borderColor: "#E7E2D4", backgroundColor: "#FBF9F2" }}>
          <div className="sans text-xs font-semibold tracking-wide text-gray-400 mb-4">PAYMENT DETAILS</div>
          <div className="sans text-sm mb-3">
            <div className="text-gray-500 mb-0.5">Bank</div>
            <div className="font-semibold" style={{ color: NAVY }}>{BANK_NAME}</div>
          </div>
          <div className="sans text-sm mb-3">
            <div className="text-gray-500 mb-0.5">Account name</div>
            <div className="font-semibold" style={{ color: NAVY }}>{ACCOUNT_NAME}</div>
          </div>
          <div className="sans text-sm mb-4">
            <div className="text-gray-500 mb-0.5">Account number</div>
            <div className="flex items-center gap-2">
              <div className="font-semibold text-lg" style={{ color: NAVY }}>{ACCOUNT_NUMBER}</div>
              <button
                onClick={() => {
                  navigator.clipboard.writeText(ACCOUNT_NUMBER);
                  setCopied(true);
                  setTimeout(() => setCopied(false), 2000);
                }}
                className="sans text-xs font-semibold px-3 py-1 rounded-full press"
                style={{ backgroundColor: copied ? GREEN : "#EAF5EC", color: copied ? "white" : GREEN_DARK }}
              >
                {copied ? "Copied!" : "Copy"}
              </button>
            </div>
          </div>
          <p className="sans text-xs text-gray-500 leading-relaxed">
            Please make payment to confirm your order, and share a screenshot of the transfer along with your
            order message via WhatsApp or email.
          </p>
        </div>
        )}

        <div className="mt-8">
          <button onClick={() => setSubmitted(false)} className="sans text-sm" style={{ color: GREEN_DARK }}>← Edit order</button>
        </div>
      </div>
    );
  }

  if (cart.length === 0) {
    return (
      <div className="max-w-lg mx-auto px-5 py-20 text-center">
        <h1 className="serif text-3xl font-bold mb-3" style={{ color: NAVY }}>Your cart is empty</h1>
        <p className="sans text-gray-600 mb-8">Head to the menu to add a parfait or yoghurt to your order.</p>
        <button onClick={() => setPage("menu")} className="px-6 py-3 rounded-full font-semibold text-white sans hover-lift press" style={{ backgroundColor: GREEN }}>
          Go to menu
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-2xl mx-auto px-5 py-14">
      {showNotice && (
        <div className="fixed inset-0 z-50 flex items-center justify-center px-5" style={{ backgroundColor: "rgba(27,41,81,0.55)" }}>
          <div className="rounded-2xl bg-white max-w-sm w-full p-7 text-center page-fade" style={{ boxShadow: "0 30px 60px -20px rgba(0,0,0,0.4)" }}>
            <div className="w-14 h-14 rounded-full flex items-center justify-center mx-auto mb-5" style={{ backgroundColor: "#EAF5EC" }}>
              <Clock size={24} style={{ color: GREEN_DARK }} />
            </div>
            <h2 className="serif text-xl font-bold mb-2" style={{ color: NAVY }}>Before you order</h2>
            <p className="sans text-sm text-gray-600 leading-relaxed mb-6">
              Everything is made fresh to order, so we kindly ask for at least <span className="font-semibold" style={{ color: NAVY }}>24 hours' notice</span> on
              all orders. Thank you for your patience — it's what keeps every parfait tasting the way it should.
            </p>
            <button
              onClick={dismissNotice}
              className="w-full py-3 rounded-full font-semibold text-white sans hover-lift press"
              style={{ backgroundColor: GREEN }}
            >
              Got it, continue
            </button>
          </div>
        </div>
      )}
      <h1 className="serif text-4xl font-bold mb-2" style={{ color: NAVY }}>Your order</h1>
      <p className="sans text-gray-600 mb-8">Review your items, then add your details below.</p>

      <div className="flex flex-col gap-3 mb-8">
        {lines.map((l) => (
          <div key={l.cartId} className="rounded-xl border p-4 flex gap-4" style={{ borderColor: "#E7E2D4" }}>
            <img src={l.product.image} alt={l.product.name} className="rounded-lg object-cover flex-shrink-0" style={{ width: 72, height: 72 }} />
            <div className="flex-1 min-w-0">
              <div className="flex items-start justify-between gap-2">
                <div className="serif font-bold" style={{ color: NAVY }}>{l.product.name}</div>
                <button onClick={() => removeFromCart(l.cartId)} className="sans text-xs text-gray-400 hover:text-red-500 flex-shrink-0 press">Remove</button>
              </div>
              {l.product.kind === "parfait" && (l.fruits.length > 0 || l.toppings.length > 0) && (
                <div className="sans text-xs text-gray-500 mt-1">
                  {l.fruits.length > 0 && <div>Fruit: {l.fruits.join(", ")}</div>}
                  {l.toppings.length > 0 && <div>Toppings: {l.toppings.join(", ")}</div>}
                </div>
              )}
              <div className="flex items-center justify-between mt-2">
                <div className="flex items-center gap-3">
                  <button onClick={() => updateCartQty(l.cartId, l.qty - 1)} className="w-7 h-7 rounded-full border flex items-center justify-center press" style={{ borderColor: "#E7E2D4" }}>
                    <Minus size={13} />
                  </button>
                  <span className="sans text-sm font-semibold w-4 text-center">{l.qty}</span>
                  <button onClick={() => updateCartQty(l.cartId, l.qty + 1)} className="w-7 h-7 rounded-full border flex items-center justify-center press" style={{ borderColor: "#E7E2D4" }}>
                    <Plus size={13} />
                  </button>
                </div>
                <div className="sans text-sm font-bold" style={{ color: GREEN_DARK }}>{naira(l.subtotal)}</div>
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="grid sm:grid-cols-2 gap-4 mb-5">
        <div>
          <label className="sans text-sm font-semibold block mb-1.5" style={{ color: NAVY }}>Your name</label>
          <input value={name} onChange={(e) => setName(e.target.value)} className="w-full border rounded-lg px-3 py-2.5 sans text-sm" style={{ borderColor: "#E7E2D4" }} placeholder="e.g. Amaka Obi" />
        </div>
        <div>
          <label className="sans text-sm font-semibold block mb-1.5" style={{ color: NAVY }}>Phone number</label>
          <input value={phone} onChange={(e) => setPhone(e.target.value)} className="w-full border rounded-lg px-3 py-2.5 sans text-sm" style={{ borderColor: "#E7E2D4" }} placeholder="080..." />
        </div>
      </div>
      <div className="mb-5">
        <label className="sans text-sm font-semibold block mb-1.5" style={{ color: NAVY }}>Email {"(only needed if paying by card)"}</label>
        <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} className="w-full border rounded-lg px-3 py-2.5 sans text-sm" style={{ borderColor: "#E7E2D4" }} placeholder="you@example.com" />
      </div>
      <div className="mb-5">
        <label className="sans text-sm font-semibold block mb-1.5" style={{ color: NAVY }}>Delivery or pickup address</label>
        <input value={address} onChange={(e) => setAddress(e.target.value)} className="w-full border rounded-lg px-3 py-2.5 sans text-sm" style={{ borderColor: "#E7E2D4" }} placeholder="Where should we bring it, or say 'pickup'" />
      </div>
      <div className="mb-8">
        <label className="sans text-sm font-semibold block mb-1.5" style={{ color: NAVY }}>Notes (optional)</label>
        <textarea value={notes} onChange={(e) => setNotes(e.target.value)} rows={3} className="w-full border rounded-lg px-3 py-2.5 sans text-sm" style={{ borderColor: "#E7E2D4" }} placeholder="Anything else we should know" />
      </div>

      <div className="flex items-center justify-between rounded-xl p-4 mb-6" style={{ backgroundColor: "#FBF9F2" }}>
        <span className="sans text-sm font-semibold" style={{ color: NAVY }}>Order total</span>
        <span className="sans text-xl font-bold" style={{ color: GREEN_DARK }}>{naira(total)}</span>
      </div>

      <div className="sans text-sm font-semibold mb-3" style={{ color: NAVY }}>How would you like to pay?</div>
      {verifyError && (
        <div className="sans text-sm rounded-lg p-3 mb-3" style={{ backgroundColor: "#FBEAEA", color: "#8A2A2A" }}>
          {verifyError}
        </div>
      )}
      {PAYSTACK_IS_LIVE && (
        <button
          disabled={!canSubmit || paying || verifying}
          onClick={payWithPaystack}
          className="w-full py-3.5 rounded-full font-semibold text-white sans disabled:opacity-40 press mb-3 flex items-center justify-center gap-2"
          style={{ backgroundColor: GREEN }}
        >
          {paying ? "Opening payment window…" : verifying ? "Confirming payment…" : <>Pay {naira(total)} now with card</>}
        </button>
      )}
      <button
        disabled={!canSubmit || paying || verifying}
        onClick={payByTransfer}
        className="w-full py-3.5 rounded-full font-semibold sans disabled:opacity-40 press"
        style={PAYSTACK_IS_LIVE ? { borderColor: NAVY, color: NAVY, border: "1px solid" } : { backgroundColor: GREEN, color: "white" }}
      >
        {PAYSTACK_IS_LIVE ? "Pay by bank transfer instead" : `Place order — pay ${naira(total)} by bank transfer`}
      </button>
      {!PAYSTACK_IS_LIVE && (
        <p className="sans text-xs text-gray-400 mt-3 text-center">
          Card payments are coming soon — for now, orders are confirmed by bank transfer.
        </p>
      )}
      {!canSubmit && <p className="sans text-xs text-gray-400 mt-2 text-center">Add your name and phone number to continue.</p>}
    </div>
  );
}

/* ---------- Root ---------- */
export default function App() {
  const [page, setPage] = useState("home");

  /* Cart lives here so items added on the Menu page carry over to Order */
  const [cart, setCart] = useState([]);

  function addToCart(item) {
    setCart((prev) => [...prev, { ...item, cartId: Date.now() + Math.random().toString(36).slice(2) }]);
  }
  function removeFromCart(cartId) {
    setCart((prev) => prev.filter((i) => i.cartId !== cartId));
  }
  function updateCartQty(cartId, qty) {
    setCart((prev) => prev.map((i) => (i.cartId === cartId ? { ...i, qty: Math.max(1, qty) } : i)));
  }
  function clearCart() {
    setCart([]);
  }

  const cartState = { cart, addToCart, removeFromCart, updateCartQty, clearCart };

  return (
    <PageShell page={page} setPage={setPage} cartCount={cart.reduce((n, i) => n + i.qty, 0)}>
      {page === "home" && <Home setPage={setPage} />}
      {page === "menu" && <MenuPage setPage={setPage} cartState={cartState} />}
      {page === "about" && <AboutPage />}
      {page === "contact" && <ContactPage />}
      {page === "feedback" && <FeedbackPage />}
      {page === "order" && <OrderPage cartState={cartState} setPage={setPage} />}
    </PageShell>
  );
}
